A developer tries to make the enrollment tests independent of Postgres:

// src/enrollments/enrollment.service.ts
@Injectable()
export class EnrollmentService {
  private readonly enrollments = new PgEnrollmentRepository();

  async enroll(userId: string, courseId: string) {
    const now = new Date();
    return this.enrollments.insert({ userId, courseId, enrolledAt: now, expiresAt: addDays(now, 30) });
  }
}

// src/enrollments/enrollment.service.spec.ts
const moduleRef = await Test.createTestingModule({
  providers: [EnrollmentService, { provide: PgEnrollmentRepository, useValue: fakeRepo }],
}).compile();
const service = moduleRef.get(EnrollmentService);
await service.enroll("u1", "c42");

CI output (the unit-test job has no database):
  ● EnrollmentService › enrolls a learner
    Error: connect ECONNREFUSED 127.0.0.1:5432

Statement: "The useValue fake is never used, because EnrollmentService creates its repository with new instead of receiving it through its constructor."

The clock is extracted so tests can control time:

// src/common/clock.ts
export interface Clock {
  now(): Date;
}

@Injectable()
export class SystemClock implements Clock {
  now(): Date { return new Date(); }
}

// src/enrollments/enrollment.service.ts
@Injectable()
export class EnrollmentService {
  constructor(private readonly clock: Clock) {}
}

// src/enrollments/enrollment.module.ts
@Module({ providers: [EnrollmentService, SystemClock] })
export class EnrollmentModule {}

Statement: "When the application starts, Nest injects SystemClock into EnrollmentService, because SystemClock is the only provider in the module that implements Clock."
